import { getGeminiKeyPoolWithRemote } from '@/lib/order-ready-tts';

const GEMINI_BASE = 'https://generativelanguage.googleapis.com/v1beta/models';
const MODERN_CHAT_MODELS = [
  'gemini-3.5-flash',
  'gemini-3.6-flash',
  'gemini-3.5-flash-lite',
  'gemini-3-flash-preview'
];
const CLASSIC_CHAT_MODELS = [
  'gemini-2.5-flash',
  'gemini-3.5-flash',
  'gemini-3.5-flash-lite'
];

// In-memory circuit breaker for depleted (402), invalid (401/403), or rate-limited (429) keys
const chatKeyQuarantineUntil = new Map<string, number>();
let chatKeyRoundRobin = 0;

async function callGeminiChatWithFailover(
  body: any,
  preferredModel?: string | null,
  preferredKey?: string | null
): Promise<{ ok: true; data: any; usedModel: string; usedKey: string } | { ok: false; status: number; error: string }> {
  const rawPool = await getGeminiKeyPoolWithRemote();
  if (rawPool.length === 0) {
    return { ok: false, status: 500, error: 'Missing Gemini API Key pool.' };
  }

  const now = Date.now();
  const activePool = rawPool.filter((k) => (chatKeyQuarantineUntil.get(k) || 0) <= now);
  const candidateKeys = activePool.length > 0 ? activePool : rawPool;

  // Rotate starting key while prioritizing modern AQ. keys first (or preferredKey if continuing a tool loop)
  const startIdx = chatKeyRoundRobin++ % candidateKeys.length;
  const rotated = [...candidateKeys.slice(startIdx), ...candidateKeys.slice(0, startIdx)];
  const modernKeys = rotated.filter((k) => k.startsWith('AQ.'));
  const classicKeys = rotated.filter((k) => !k.startsWith('AQ.'));
  let orderedKeys = [...modernKeys, ...classicKeys];
  if (preferredKey && orderedKeys.includes(preferredKey)) {
    orderedKeys = [preferredKey, ...orderedKeys.filter((k) => k !== preferredKey)];
  }

  let lastStatus = 500;
  let lastError = 'AI service temporarily unavailable.';

  for (const key of orderedKeys) {
    const defaultModels = key.startsWith('AQ.') ? MODERN_CHAT_MODELS : CLASSIC_CHAT_MODELS;
    const modelsToTry = preferredModel
      ? [preferredModel, ...defaultModels.filter((m) => m !== preferredModel)]
      : defaultModels;

    for (const model of modelsToTry) {
      const url = `${GEMINI_BASE}/${model}:generateContent?key=${key}`;
      try {
        const res = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(body)
        });
        const data = await res.json().catch(() => ({}));

        if (res.ok && data?.candidates?.[0]?.content?.parts) {
          return { ok: true, data, usedModel: model, usedKey: key };
        }

        const errMsg = data?.error?.message || `HTTP ${res.status}`;
        lastStatus = res.status;
        lastError = errMsg;
        console.warn(`[TEG Assistant Failover] Key ${key.slice(0, 8)}... / Model ${model} failed (${res.status}): ${errMsg.slice(0, 120)}`);

        // 402 = Prepayment credits depleted, 401/403 = Key invalid/revoked -> Quarantine key for 6 hours and switch key immediately
        if (res.status === 402 || res.status === 401 || res.status === 403 || /prepayment credits|depleted|API key not valid/i.test(errMsg)) {
          chatKeyQuarantineUntil.set(key, Date.now() + 6 * 60 * 60 * 1000);
          break; // Break model loop -> try next key
        }

        // 429 = Quota/Rate limit on this key -> Quarantine key for 2 minutes and switch key immediately
        if (res.status === 429) {
          chatKeyQuarantineUntil.set(key, Date.now() + 2 * 60 * 1000);
          break; // Break model loop -> try next key
        }

        // 404 (model not available for this key tier) or 503 (model high demand spike) -> Try next model on same key
        if (res.status === 404 || res.status === 503 || res.status === 500) {
          continue;
        }
      } catch (netErr: any) {
        lastError = netErr?.message || 'Network error';
        console.warn(`[TEG Assistant Failover] Network error on ${model}:`, lastError);
        continue;
      }
    }
  }

  return { ok: false, status: lastStatus, error: lastError };
}

// Reliable PST business date (matches toast-api.ts pattern exactly)
function getBusinessDates() {
  const now = new Date();
  const todayStr = now.toLocaleDateString('en-CA', { timeZone: 'America/Los_Angeles' });
  const laHour = parseInt(now.toLocaleTimeString('en-US', { hour: 'numeric', hour12: false, timeZone: 'America/Los_Angeles' }));
  let businessToday = todayStr;
  if (laHour < 6) {
    const d = new Date(now);
    d.setDate(d.getDate() - 1);
    businessToday = d.toLocaleDateString('en-CA', { timeZone: 'America/Los_Angeles' });
  }
  const [y, m, day] = businessToday.split('-').map(Number);
  const yd = new Date(y, m - 1, day);
  yd.setDate(yd.getDate() - 1);
  const businessYesterday = `${yd.getFullYear()}-${String(yd.getMonth()+1).padStart(2,'0')}-${String(yd.getDate()).padStart(2,'0')}`;
  return { today: businessToday, yesterday: businessYesterday, laHour };
}

const fmt$ = (n: number) => '$' + n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const clean = (name: string) => (name || '').replace(/^Tacos Gavilan\s+/i, '').trim();

// ── Lightweight context (quick summary, NOT exhaustive) ──
async function fetchLightContext(user?: any): Promise<string> {
  try {
    const { today, yesterday, laHour } = getBusinessDates();
    const [y, m, day] = today.split('-').map(Number);
    const todayDate = new Date(Date.UTC(y, m - 1, day, 12, 0, 0));
    
    // Day of week: 0=Sun, 1=Mon, ..., 6=Sat
    const dayOfWeek = todayDate.getUTCDay();
    const mondayOffset = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
    
    // This week (Monday to today)
    const thisMon = new Date(todayDate);
    thisMon.setUTCDate(thisMon.getUTCDate() + mondayOffset);
    const thisWeekStart = thisMon.toISOString().slice(0, 10);
    const thisWeekEnd = today;

    // Last week (Monday to Sunday)
    const lastMon = new Date(thisMon);
    lastMon.setUTCDate(lastMon.getUTCDate() - 7);
    const lastSun = new Date(thisMon);
    lastSun.setUTCDate(lastSun.getUTCDate() - 1);
    const lastWeekStart = lastMon.toISOString().slice(0, 10);
    const lastWeekEnd = lastSun.toISOString().slice(0, 10);

    // Two weeks ago / Semana antepasada (Monday to Sunday)
    const twoWeeksMon = new Date(lastMon);
    twoWeeksMon.setUTCDate(twoWeeksMon.getUTCDate() - 7);
    const twoWeeksSun = new Date(lastMon);
    twoWeeksSun.setUTCDate(twoWeeksSun.getUTCDate() - 1);
    const twoWeeksAgoStart = twoWeeksMon.toISOString().slice(0, 10);
    const twoWeeksAgoEnd = twoWeeksSun.toISOString().slice(0, 10);

    // This month (1st to today)
    const thisMonthStart = `${today.slice(0, 7)}-01`;
    const thisMonthEnd = today;

    // Last month (1st to last day of previous month)
    const prevMonthDate = new Date(Date.UTC(y, m - 2, 1, 12, 0, 0));
    const lastMonthYear = prevMonthDate.getUTCFullYear();
    const lastMonthNum = String(prevMonthDate.getUTCMonth() + 1).padStart(2, '0');
    const lastDayOfPrevMonth = new Date(Date.UTC(y, m - 1, 0, 12, 0, 0)).getUTCDate();
    const lastMonthStart = `${lastMonthYear}-${lastMonthNum}-01`;
    const lastMonthEnd = `${lastMonthYear}-${lastMonthNum}-${String(lastDayOfPrevMonth).padStart(2, '0')}`;

    const sections: string[] = [];
    sections.push(`🕐 California time: ${laHour}:00 | Business day: ${today} | Yesterday: ${yesterday}`);

    // Quick today's total
    const { data: todaySales } = await supabaseAdmin
      .from('sales_daily_cache')
      .select('net_sales, labor_cost')
      .eq('business_date', today);
    const tTotal = (todaySales || []).reduce((s, r) => s + (Number(r.net_sales) || 0), 0);
    const tLabor = (todaySales || []).reduce((s, r) => s + (Number(r.labor_cost) || 0), 0);
    if (tTotal > 0) {
      sections.push(`📊 Today sales: ${fmt$(tTotal)} | Labor: ${fmt$(tLabor)} (${((tLabor/tTotal)*100).toFixed(1)}%)`);
    } else {
      sections.push(`📊 Today: Day in progress, data updating from Toast POS.`);
    }

    // Yesterday quick
    const { data: yestSales } = await supabaseAdmin
      .from('sales_daily_cache')
      .select('net_sales')
      .eq('business_date', yesterday);
    const yTotal = (yestSales || []).reduce((s, r) => s + (Number(r.net_sales) || 0), 0);
    if (yTotal > 0) sections.push(`📊 Yesterday: ${fmt$(yTotal)}`);

    // Store count
    const { data: stores } = await supabaseAdmin.from('stores').select('name');
    if (stores?.length) sections.push(`🏪 Stores (${stores.length}): ${stores.map(s => clean(s.name)).join(', ')}`);

    // Complete period reference calendar for AI tools
    sections.push(`📅 CALENDARIO EXACTO DE PERIODOS PARA CONSULTAS:`);
    sections.push(`• Hoy (Today): ${today}`);
    sections.push(`• Ayer (Yesterday): ${yesterday}`);
    sections.push(`• Esta semana (This week): ${thisWeekStart} al ${thisWeekEnd}`);
    sections.push(`• Semana pasada (Last week): ${lastWeekStart} al ${lastWeekEnd}`);
    sections.push(`• Semana antepasada (Two weeks ago): ${twoWeeksAgoStart} al ${twoWeeksAgoEnd}`);
    sections.push(`• Este mes (This month): ${thisMonthStart} al ${thisMonthEnd}`);
    sections.push(`• Mes pasado (Last month): ${lastMonthStart} al ${lastMonthEnd}`);

    // Recent user question history for predictive personalization
    if (user && (user.email || user.id)) {
      try {
        let q = supabaseAdmin
          .from('assistant_conversations')
          .select('title, updated_at')
          .order('updated_at', { ascending: false })
          .limit(5);

        if (user.email && user.id) {
          q = q.or(`user_email.eq.${user.email},user_id.eq.${user.id}`);
        } else if (user.email) {
          q = q.eq('user_email', user.email);
        } else if (user.id) {
          q = q.eq('user_id', user.id);
        }

        const { data: pastConvs } = await q;
        if (pastConvs && pastConvs.length > 0) {
          sections.push(`🧠 TEMAS E HISTORIAL DE CONSULTAS RECIENTES DEL USUARIO (Usa esto para predecir preguntas de seguimiento contextualmente relevantes para su tienda/rol):`);
          pastConvs.forEach(c => sections.push(`• "${c.title}"`));
        }
      } catch (e) {
        // Non-blocking
      }
    }

    return sections.join('\n');
  } catch (e) {
    return `Error loading context: ${(e as Error).message}`;
  }
}

